def has_no_zeros(n):
    return '0' not in str(n)

def solve_fast(m_digits):
    # Max possible A is m_digits - 1.
    for A in range(m_digits - 1, -1, -1):
        # We want to find if there exists N such that
        # there's an M in [N * 10^A, N * 10^A + N - 1]
        # with m_digits and no zeros.

        # M has m_digits, so 10^(m-1) <= M < 10^m.
        # Also M is in [N * 10^A, N * 10^A + N - 1].
        # This means N * 10^A < 10^m and N * 10^A + N - 1 >= 10^(m-1).
        # So N < 10^(m-A) and N >= 10^(m-1) / (10^A + 1).

        n_start = 10**(m_digits - 1) // (10**A + 1)
        n_end = 10**(m_digits - A)

        for N in range(max(1, n_start), n_end + 1):
            # Check if there's any M in [N * 10^A, N * 10^A + N - 1]
            # that has no zeros and is within [10^(m-1), 10^m - 1].
            low = max(N * 10**A, 10**(m_digits - 1))
            high = min(N * 10**A + N - 1, 10**m_digits - 1)

            if low > high:
                continue

            # Now we need to check if any M in [low, high] has no zeros.
            # This could still be a large range.
            # But wait, if high - low is large, we are likely to find one.
            # If high - low is small, we can just iterate.
            if high - low < 1000:
                for M in range(low, high + 1):
                    if has_no_zeros(M):
                        return A
            else:
                # If the range is large, we can probably find an M.
                # Let's try to find one.
                # A simple way to find M with no zeros:
                # just try some values.
                for M in range(low, low + 1000):
                    if has_no_zeros(M):
                        return A
                # This is not a complete check.
                # Let's use a more robust method to find if there's any M in [low, high] with no zeros.
                if find_no_zero(low, high):
                    return A
    return 0

def find_no_zero(low, high):
    # Check if there is any number in [low, high] with no zero digits.
    # This can be done by a recursive search.
    s_low = str(low)
    s_high = str(high)
    if len(s_low) != len(s_high):
        # The range spans across different numbers of digits.
        # But we know low and high have the same number of digits in our case.
        pass

    def search(idx, current_val, is_less, is_greater):
        if idx == len(s_low):
            return True

        lower = int(s_low[idx]) if not is_greater else 1
        upper = int(s_high[idx]) if not is_less else 9

        for d in range(max(1, lower), upper + 1):
            if search(idx + 1, current_val * 10 + d, is_less or (d < upper), is_greater or (d > lower)):
                return True
        return False

    return search(0, 0, False, False)

