def check_A(m, A):
    # Try all Q with A zeros and m digits (or fewer)
    # But let's just try Q = d * 10^A
    for d in range(1, 10):
        Q = d * 10**A
        # We need to find N such that there's an M in [Q*N, (Q+1)*N - 1]
        # with m digits and no zeros.
        # 10**(m-1) <= M < 10**m
        # Q*N <= M < (Q+1)*N

        # N can be roughly 10**(m-1) / Q
        n_start = 10**(m-1) // (Q + 1)
        n_end = 10**m // Q + 1
        for N in range(max(1, n_start), n_end + 1):
            low = max(Q * N, 10**(m-1))
            high = min((Q + 1) * N - 1, 10**m - 1)
            if low > high:
                continue
            if high - low < 1000:
                for M in range(low, high + 1):
                    if has_no_zeros(M):
                        return True
            else:
                # We can't check all, but we can check some
                for M in range(low, low + 1000):
                    if has_no_zeros(M):
                        return True
                # Let's also check some random ones
                import random
                for _ in range(1000):
                    M = random.randint(low, high)
                    if has_no_zeros(M):
                        return True
    return False

